d=[]
d.append(dict(description='A historian of science who studies how trust, personal character and institutions sustain knowledge. His Scientific Life interview questions sharp distinctions between academic virtue and industrial self-interest, and argues that scientific uncertainty can make personal credibility more important.',sources=[s('Steven Shapin, Chicago Press author interview on The Scientific Life (2008)','https://press.uchicago.edu/Misc/Chicago/750248in.html',P,'Complete written author interview read. Answers on virtue, institutional settings, commercial research and entrepreneurial uncertainty used; whole book unread.'),s('Steven Shapin, Harvard author bibliography','https://shapin.scholars.harvard.edu/-publications',M,'Author-maintained bibliography checked for1985coauthored Leviathan,1994Social History,1996Scientific Revolution; later2011/2018editions distinguished. Simon Schaffer retains coauthor credit.')],works=[w(1985,'Leviathan and the Air-Pump (with Simon Schaffer)',1),w(1994,'A Social History of Truth',1),w(1996,'The Scientific Revolution',1)],edges=[e('science','Examines changing grounds for the moral and epistemic authority of scientists.','Own interview distinguishes virtue attributed to individuals and institutions; does not deny knowledge of nature.'),e('sts','Questions simple academic/industrial contrasts and studies credibility under entrepreneurial uncertainty.','Own interview treats commercial science as a historically specific social setting; commercial profit is not asserted to explain every scientific judgment.')]))
d.append(dict(description='A historian of modern Britain who connects aristocratic power to urban development and writes biography as a problem of proportion and judgment. His interview explains how aristocratic ground rents and urban growth complicate a simple division between landed elites and the industrial city.',sources=[s('David Cannadine interviewed by James Rivington, British Academy Review31,11 November2017','https://www.thebritishacademy.ac.uk/publishing/review/31/david-cannadine-interview/',P,'Interview answers on aristocracy/Edgbaston, biography/Thatcher and ODNB read, with footnotes for1980Lords,1990Decline,1998Class. Other policy/current-event answers not used as historical claims.'),s('Princeton Dean of Faculty: David Cannadine retrospective','https://dof.princeton.edu/people/david-cannadine',M,'Institutional bibliography confirms1990Decline,1998Class in Britain and2001Ornamentalism original; Penguin2002edition not substituted.')],works=[w(1990,'The Decline and Fall of the British Aristocracy',1),w(1998,'Class in Britain',1),w(2001,'Ornamentalism',1)],edges=[e('social','Connects aristocratic wealth and power to urban development as well as rural landholding.','Own interview describes Calthorpe ground rents and Edgbaston, motivating a broader social history of aristocracy.'),e('biography','Treats biography as a balance of private/public life, evidence, proportion and competing historical judgments.','Own interview’s ODNB and Thatcher answers explain the method; his acknowledgment of underrepresented women/businesspeople concerns an editorial programme, not sole authorship of dictionary lives.')]))
d.append(dict(description='A historian of modern France whose Peasants into Frenchmen interprets national integration as a late and uneven transformation. Maurice Agulhon’s substantive review recognizes the combination of transport, markets, schooling and military service, while questioning the weight assigned to deliberate republican intervention.',sources=[s('Maurice Agulhon, review of Peasants into Frenchmen, Annales33.4(1978),843–844','https://www.persee.fr/doc/ahess_0395-2649_1978_num_33_4_293975_t1_0843_0000_001',P,'Page843 read in Persée text;844not read. Named reader explains spontaneous economic change versus deliberate education/integration, and notes chronological emphasis. Weber’s monograph unread; page’s erroneous Stanford faculty designation not adopted.'),s('University of California Senate, Eugen Weber memorial, Ronald Mellor, Lynn Hunt, Bariša Krekic and Robert Wohl','https://senate.universityofcalifornia.edu/_files/inmemoriam/html/eugenweber.html',P,'Institutional memorial and bibliography inspected: life years1925–2007, France:Fin de Siècle1986, Hollow Years1994; Peasants publication year independently checked.'),s('Wellcome Collection: Peasants into Frenchmen','https://wellcomecollection.org/works/eabuywf8',M,'Stanford1976publication checked;1983French translation remains separate.')],works=[w(1976,'Peasants into Frenchmen',2),w(1986,'France: Fin de Siècle',1),w(1994,'The Hollow Years',1)],edges=[e('nationalismstudies','Interprets French national belonging as historically produced through uneven rural integration.','Agulhon’s substantive review843reports the thesis and questions its political periodization; not automatic adoption of the modernization label.'),e('social','Combines markets and transport with schools and conscription as mechanisms of rural transformation.','Agulhon credits the plural account while asking whether deliberate state integration is given too much weight; the critique remains explicit.')],life=dict(status='deceased',death_year=2007,death_precision='year',sources=[(1,'UC Senate memorial heading1925–2007 and opening','Explicit death year and UCLA modern-France historian identity.')],limits='Institutional year evidence checked; no precise death day claimed here.')))
d.append(dict(description='A social historian of emotions who distinguishes emotional standards from experience without treating them as unrelated. His interview connects emotional inquiry to family, gender, work and social protest, and rejects the idea that his approach should only study prescriptive culture.',sources=[s('Jan Plamper, interviews with Reddy, Rosenwein and Stearns, History and Theory49.2(May2010),237–265','https://doi.org/10.1111/j.1468-2303.2010.00541.x',P,'Addendum for Peter N. Stearns entry: his answers at261–263read in Barbara Rosenwein’s author-uploaded ResearchGate text (https://www.researchgate.net/publication/261926040_THE_HISTORY_OF_EMOTIONS_AN_INTERVIEW_WITH_WILLIAM_REDDY_BARBARA_ROSENWEIN_AND_PETER_STEARNS). Standards versus experience and relation to social history read. Earlier Reddy/Rosenwein reading limits remain; remaining Stearns section264–265not systematically read. January upload indexing rejected in favor of May issue.','dc166_plamper_interview_2010'),s('Peter N. Stearns and Carol Z. Stearns, “Emotionology”, AHR90.4(1985),813–836','https://academic.oup.com/ahr/article-abstract/90/4/813/86586',M,'Journal masthead/metadata checked for October1985and joint authorship; original article body not claimed read.'),s('Vermont State Colleges Libraries: Anger','https://catalog.libraries.vsc.edu/cgi-bin/koha/opac-detail.pl?biblionumber=106356',M,'Catalogue gives Carol Zisowitz Stearns first and Peter N.Stearns second, Chicago1986. Later paperback dates not substituted.'),s('NYU Press: American Cool','https://nyupress.org/9780814779965/american-cool/',M,'Publisher gives April1994, Peter N.Stearns; whole book unread.')],works=[w(1985,'“Emotionology” (with Carol Z. Stearns)',1),w(1986,'Anger (Carol Zisowitz Stearns and Peter N. Stearns)',2),w(1994,'American Cool',3)],edges=[e('history_of_emotions','Distinguishes emotional standards from emotional experience while investigating relations between them.','Own2010answer262insists cultural prescription does not necessarily describe experience; joint earlier concept credit to Carol Z.Stearns retained.'),e('social','Connects emotions to social action, work and family without discarding rational interests.','Own2010answer263makes emotional cues a component of social history, rather than a replacement for the history of interests.')]))
d.append(dict(description='An intellectual historian of empire and international political ideas. His interview connects European self-understanding to overseas encounters and distinguishes the modern project of European union from an empire, while stating his own cosmopolitan and progress-oriented commitments.',sources=[s('Anthony Pagden interviewed by Fernando Gomez Herrero, “In Pursuit of Europe”, Not Even Past, PartI','https://notevenpast.org/in-pursuit-of-europe-an-interview-with-anthony-pagden-part-i/',P,'PartIwritten interview read, especially first answers on empire/European unity and historicizing. Intro’s1987Fall/2015Enlightenment dates are edition-level or erroneous for originals and not adopted. Pagden’s explicit commitment to progress is attributed, not turned into an objective law.'),s('Cambridge scholarly bibliography, European Conquest and the Rights of Indigenous Peoples','https://www.cambridge.org/core/books/abs/european-conquest-and-the-rights-of-indigenous-peoples/select-bibliography/4715E2FDFFA24D1A87DF44171C3F9690',M,'Bibliographic entries checked: Fall of Natural Man1982, European Encounters1993,Lords1995. Publication facts only; no substantive claim from a bibliography.')],works=[w(1982,'The Fall of Natural Man',1),w(1993,'European Encounters with the New World',1),w(1995,'Lords of All the World',1)],edges=[e('intellectualhistory','Studies European political self-understanding through ideas of empire and relations with peoples outside Europe.','Own interview relates Hispanic/Amerindian encounters to European categories, not simply Spanish national ideas.'),e('global','Connects projects of European unity with imperial experience and changing international arrangements.','Own interview distinguishes Europe’s aggregate of states from empire, while acknowledging imperial preservation as part of the history. His cosmopolitan-progressive evaluation remains his position.')]))
d.append(dict(description='A historian of gender and American public life whose research follows women’s access to politics beyond formal suffrage. Nancy Fraser’s substantive reading uses Ryan’s evidence of associations, street protest and public participation to question the identification of public life with one bourgeois arena.',sources=[s('Nancy Fraser, “Rethinking the Public Sphere”, Social Text25/26(1990),56–80','https://fswg.wordpress.com/wp-content/uploads/2013/08/fraser-rethinking-the-public-sphere.pdf',P,'Addendum for Mary Ryan entry:61read, with59–62context. Fraser explicitly describes Ryan’s evidence of women’s associations, protest and multiple public arenas. This is named substantive reader mediation; Ryan’s original text not read. Earlier source locators and qualifications remain.','fraser_sphere_primary'),s('UC Press, Civic Wars, publisher metadata and author biography mirrored in Google Books','https://books.google.com/books/about/Civic_Wars.html?id=cGHwTYIkG3UC',M,'Publisher-supplied bibliographic/author information checked: Civic Wars1997, Cradle1981, Women in Public1990. Google Books labels the electronic issue reprint/revised; no content argument derived from this metadata.'),s('Smithsonian Libraries: Women in Public','https://www.si.edu/object/women-public-between-banners-and-ballots-1825-1880-mary-p-ryan%3Asiris_sil_398842',M,'Custodial library record dates original1990; current Hopkins paperback1992distinct.')],works=[w(1981,'Cradle of the Middle Class',1),w(1990,'Women in Public',2),w(1997,'Civic Wars',1)],edges=[e('women','Documents women’s public political activity through associations, protests and street participation despite exclusion from suffrage.','Fraser61explicitly attributes these historical findings to Ryan; different classes/ethnicities use different routes, not one universal female experience.'),e('frankfurt','Provides historical evidence against equating public politics with a single bourgeois public sphere.','Fraser61uses Ryan’s findings to critique Habermas; this is Fraser’s mediated deployment of Ryan, not evidence Ryan adopted every element of Fraser’s theory or belonged to the Frankfurt School.',0,'critique')]))
d.append(dict(description='A historian of American politics and collective action whose work joins grassroots conservatism, Prohibition and transnational protest. Her Prohibition interview explains selective enforcement and federal coercive expansion while refusing to make the1920s a sufficient cause of today’s prison system.',sources=[s('Lisa McGirr interviewed by Timothy Shenk, “Booked:The War on Booze”, Dissent,11 February2016','https://dissentmagazine.org/online_articles/booked-war-on-alcohol-lisa-mcgirr-interview-prohibition-kkk/',P,'Written interview read, particularly Herrin/Klan, federal enforcement, Cohen and modernity answers. She explicitly says Prohibition did not cause the entire contemporary carceral state; retained.'),s('Harvard Magazine: Lisa McGirr,1 July2001','https://www.harvardmagazine.com/2001/07/lisa-mcgirr-html',M,'Contemporary institutional report identifies Suburban Warriors published spring2001; not a whole-book reading.'),s('Lisa McGirr,“The Passion of Sacco and Vanzetti:A Global History”, JAH93.4(March2007),1085–1115','https://academic.oup.com/jah/article-abstract/93/4/1085/702421',P,'Publisher metadata and opening extract read: local case became international mobilisation through existing networks. Remainder not read; no independent entire-article claim. Dissent identifies War on Alcohol2015.')],works=[w(2001,'Suburban Warriors',1),w(2007,'“The Passion of Sacco and Vanzetti:A Global History”',2,'Journal masthead dates March2007; opening extract only read.'),w(2015,'The War on Alcohol',0)],edges=[e('political','Reinterprets Prohibition as consequential state-building and political realignment.','Own interview describes expanded enforcement while expressly denying it alone caused the later carceral state.'),e('racial_formation','Shows Prohibition enforcement becoming an instrument of white Protestant supremacy and unequal coercion.','Own Herrin answer identifies Klan recruitment and selective action against ethnic/religious targets; one locality is not presented as every locality.')]))
d.append(dict(description='A historian of American nativism, ethnicity and historiography who combined a commitment to pluralist democracy with criticism of flattened consensus narratives. Dorothy Ross’s retrospective also notes his unease with later fragmentation, rather than assigning him a single unchanging position.',sources=[s('Dorothy Ross,“John Higham(1920–2003)”, AHA Perspectives,1 October2003','https://www.historians.org/perspectives-article/john-higham-1920-2003-october-2003/',P,'Complete memorial text read. Ross substantively discusses Strangers1955,History1965,Send These to Me1975/1984,and changing historiographic positions. Her claim of first naming/criticizing consensus in1962is qualified by the existing1959primary source and not adopted.'),s('John Higham,“The Cult of the American Consensus”, Commentary,February1959','https://www.commentary.org/articles/john-higham/the-cult-of-the-american-consensushomogenizing-our-history/',P,'Existing complete primary reading retained and reused for the individual critique. No new whole-book reading; the original source’s distinctions between Hartz/Boorstin and caveats remain.','higham_consensus_primary')],works=[w(1955,'Strangers in the Land'),w(1959,'“The Cult of the American Consensus”',1,'Original Commentary essay February1959; not memorial’s1962claim of priority.'),w(1975,'Send These to Me',0,'Ross distinguishes1975and1984editions; first date selected.')],edges=[e('nationalismstudies','Studies nativism and ethnic relations as central to American nationalism and pluralism.','Dorothy Ross’s substantive retrospective describes the project and later revisions; the nativism interpretation is not an endorsement of exclusion.'),e('progressive','Criticizes consensus narratives that flatten conflict and diversity in American history.','Existing complete1959primary reading, with original qualifications preserved; does not imply a wholesale return to older economic dualisms.',1,'critique')],life=dict(status='deceased',death_year=2003,death_date='2003-07-26',death_precision='day',sources=[(0,'AHA memorial opening','Explicit death26July2003inBaltimore, identifying the American ethnicity/cultural historian.')],limits='Precise date checked in professional-association memorial; no career interval inferred.')))
d.append(dict(description='A historian of religious mentalities who examined collective fear, insecurity and hope in early modern Western Christianity. His methodological interview presents interdisciplinary inquiry as necessary but warns that psychological interpretation must respect the limits of historical documentation.',sources=[s('Jean Delumeau interviewed by Bernard Paillard,“La peur et l’historien”, Communications57(1993),17–23','https://www.persee.fr/doc/comm_0588-8018_1993_num_57_1_1863',P,'Page17introductory account by named interviewer Bernard Paillard read, including interdisciplinary seminar and warnings about weak documentary foundations. Later interview pages18–23not read; introduction is not misrepresented as a verbatim Delumeau answer.'),s('Collège de France: Jean Delumeau biography','https://www.college-de-france.fr/fr/personne/jean-delumeau',M,'Institutional biography dates Christianisme1977,Peur1978,Péché1983and death13January2020. Metadata supports dates and identity only.'),s('Jean Delumeau interviewed by Michèle Fringeli,APIC,20November1991','https://cath.ch/newsf/apic-interview-19-2',P,'Written interview and biographical inset read, distinguishing his Christian/ecumenical commitments from history’s unpredictability; inset summarizes fear/security research and planned paradise work. Planned1992publication is not converted into confirmed publication fact.')],works=[w(1977,'Le Christianisme va-t-il mourir ?',1),w(1978,'La Peur en Occident',1),w(1983,'Le Péché et la Peur',1)],edges=[e('history_of_emotions','Makes changing collective fears and searches for security objects of historical inquiry.','Paillard’s substantive introduction and Delumeau’s1991research inset support this; no claim that all fear has one unchanging religious cause.'),e('psychohistory','Warns that psychological interpretations of the past must respect documentary limits and disciplinary methods.','Paillard17reports Delumeau’s position, including caution about sparse or contested evidence and Freud’s critique of religion; this is a specific methodological criticism, not rejection of all psychology.',0,'critique')],life=dict(status='deceased',death_year=2020,death_date='2020-01-13',death_precision='day',sources=[(1,'Final biographical paragraph','Explicitly died13January2020atBrest; religious-mentalities historian identity.')],limits='Precise death date checked in institutional biography; no career interval inferred.')))
